-- Access path: test schema indexes and scans.
INSERT INTO account_transaction (tran_id, account_id, account_sequence, amount, balance_after, inout_type, tran_type, print_content, counterparty_bank_code, counterparty_account_no, counterparty_name, channel, terminal_id, request_id, transfer_id, reversal_of, business_date, occurred_at, recorded_at)
SELECT tran_id, account_id, account_sequence, amount, balance_after, inout_type, tran_type, print_content, counterparty_bank_code, counterparty_account_no, counterparty_name, channel, terminal_id, request_id, transfer_id, reversal_of, TO_DATE(business_date, 'YYYY-MM-DD'), TO_TIMESTAMP_TZ(occurred_at, 'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM'), TO_TIMESTAMP_TZ(recorded_at, 'YYYY-MM-DD"T"HH24:MI:SS.FF6TZH:TZM')
FROM JSON_TABLE(:saved, '$' COLUMNS (tran_id NUMBER PATH '$.tran_id', account_id NUMBER PATH '$.account_id', account_sequence NUMBER PATH '$.account_sequence', amount NUMBER PATH '$.amount', balance_after NUMBER PATH '$.balance_after', inout_type VARCHAR2(10) PATH '$.inout_type', tran_type VARCHAR2(20) PATH '$.tran_type', print_content VARCHAR2(20 CHAR) PATH '$.print_content', counterparty_bank_code VARCHAR2(3) PATH '$.counterparty_bank_code', counterparty_account_no VARCHAR2(16) PATH '$.counterparty_account_no', counterparty_name VARCHAR2(60 CHAR) PATH '$.counterparty_name', channel VARCHAR2(10) PATH '$.channel', terminal_id VARCHAR2(20) PATH '$.terminal_id', request_id VARCHAR2(26) PATH '$.request_id', transfer_id NUMBER PATH '$.transfer_id', reversal_of NUMBER PATH '$.reversal_of', business_date VARCHAR2(10) PATH '$.business_date', occurred_at VARCHAR2(60) PATH '$.occurred_at', recorded_at VARCHAR2(60) PATH '$.recorded_at'))
